<?php
declare(strict_types=1);
if(!defined('PLEKSI_APP')){http_response_code(404);exit;}
function product_options(mixed $options=[]): array {
 if(!is_array($options)||!array_is_list($options)||count($options)>8)fail('En fazla 8 ürün seçeneği tanımlayın.');$seen=[];$out=[];
 foreach($options as $o){if(!is_array($o)||!valid_text($o['name']??null,1,40)||!is_array($o['values']??null)||!array_is_list($o['values'])||count($o['values'])<1||count($o['values'])>30)fail('Seçenek adı ve 1–30 farklı değer yazın.');$name=trim($o['name']);$key=mb_strtolower(str_replace('İ','i',$name));if(isset($seen[$key])||in_array($key,['__proto__','constructor','prototype'],true))fail('Seçenek adları benzersiz olmalı.');$seen[$key]=true;$values=[];$keys=[];foreach($o['values'] as $v){if(!valid_text($v,1,80))fail('Seçenek değeri 1–80 karakter olmalı.');$v=trim($v);$k=mb_strtolower(str_replace('İ','i',$v));if(isset($keys[$k]))fail('Seçenek değerleri tekrarlanamaz.');$keys[$k]=true;$values[]=$v;}$out[]=['name'=>$name,'values'=>$values];}return $out;
}
function order_option_selections(array $p,mixed $input=[]): array {
 $options=$p['options']??[];if(!$options)return [];if(!is_array($input))fail($p['name'].' için seçenekler geçersiz.');$names=array_column($options,'name');foreach(array_keys($input) as $key)if(!in_array((string)$key,$names,true))fail($p['name'].' için seçenekler geçersiz.');$out=[];foreach($options as $o){$v=$input[$o['name']]??null;if(!is_string($v)||!in_array($v,$o['values'],true))fail($p['name'].' için '.$o['name'].' seçin.');$out[$o['name']]=$v;}return $out;
}
function validate_product(array $p,array $old=[]): void {global $user;product_options($p['options']??[]);
 if(!valid_text($p['name']??null,2,150)||!valid_text($p['description']??null,0,3000)||!valid_text($p['category']??null,1,100)||!money_value($p['price']??null,1)||!money_value($p['commissionPercent']??null,0,100)||!is_bool($p['requireText']??null)||!is_bool($p['requireImage']??null)||!is_array($p['images']??null)||count($p['images'])>3||count(array_unique($p['images']))!==count($p['images']))fail('Ürün adı, fiyat, %0–100 komisyon ve en fazla üç görseli kontrol edin.');
 foreach($p['images'] as $id)if(!is_string($id)||(!in_array($id,$old['images']??[],true)&&!one('SELECT id FROM ph_uploads WHERE id=? AND user_id=?',[$id,$user['id']])))fail('Ürün görseli geçersiz.');
 if(isset($p['showOnHome'])&&!is_bool($p['showOnHome']))fail('Ana sayfa görünürlüğü geçersiz.');
 if(isset($p['active'])&&!is_bool($p['active']))fail('Ürün yayın durumu geçersiz.');
}
function delete_products(mixed $ids): int {if(!is_array($ids)||!count($ids)||count($ids)>1000||count($ids)!==count(array_unique($ids)))fail('Silinecek ürünleri seçin.');foreach($ids as $id)if(!is_int($id)||$id<1)fail('Ürün seçimi geçersiz.');sort($ids);return atomic(function()use($ids){foreach($ids as $id)if(!one('SELECT id FROM ph_products WHERE id=? FOR UPDATE',[$id]))fail('Seçimdeki ürün artık bulunamıyor. Listeyi yenileyin.',409);foreach($ids as $id)sql('DELETE FROM ph_products WHERE id=?',[$id]);return count($ids);});}
function category_names(bool $admin=false): array {$names=dec(setting('categories','[]'));foreach(catalog() as $p)if($admin||($p['active']??true))$names[]=$p['category'];$names=array_values(array_unique(array_filter($names,fn($n)=>is_string($n)&&$n!=='')));sort($names,SORT_NATURAL|SORT_FLAG_CASE);return $names;}
function local_product_image(string $path): array {
 $path=rawurldecode($path);if(!str_starts_with($path,'/')||str_starts_with($path,'//')||str_contains($path,"\0")||str_contains($path,'\\')||preg_match('~(?:^|/)\.[^/]*(?:/|$)|[?#]~',$path)||!preg_match('~\.(jpe?g|png|webp)$~i',$path))fail('Site içindeki doğrudan JPG, PNG veya WebP dosya yolunu kullanın.');
 $root=realpath($_SERVER['DOCUMENT_ROOT']??dirname(__DIR__));$file=$root?realpath($root.$path):false;if(!$file||!is_file($file)||!str_starts_with($file,$root.DIRECTORY_SEPARATOR)||!is_readable($file))fail('Görsel dosyası sunucuda bulunamadı: '.$path);$size=filesize($file);if($size===false||$size>5*1024*1024)fail('Görsel 5 MB sınırını aşıyor: '.$path);$info=@getimagesize($file);if(!$info||!in_array($info['mime']??'',['image/png','image/jpeg','image/webp'],true)||$info[0]*$info[1]>40000000)fail('Geçerli bir ürün görseli değil: '.$path);return ['path'=>$file,'mime'=>$info['mime']];
}
function storefront_snapshot(): array {global $user;$products=array_values(array_filter(catalog(),fn($p)=>$p['active']??true));if(!is_dealer($user)||($user['must_change_password']??false))foreach($products as &$p){unset($p['dealerPrice'],$p['commissionPercent']);}unset($p);$names=dec(setting('categories','[]'));foreach($products as $p)$names[]=$p['category'];$names=array_values(array_unique($names));sort($names,SORT_NATURAL|SORT_FLAG_CASE);return ['products'=>$products,'categories'=>$names,'user'=>$user?safe_user($user):null,'deliveryOptions'=>delivery_options()];}
function admin_product_page(): array {
 $where=[];$args=[];$status=$_GET['status']??'all';$category=trim((string)($_GET['category']??''));$q=trim((string)($_GET['q']??''));
 if(!in_array($status,['all','active','passive'],true)||mb_strlen($q)>150||mb_strlen($category)>100)fail('Ürün filtresi geçersiz.');
 if($status!=='all')$where[]="COALESCE(JSON_UNQUOTE(JSON_EXTRACT(data,'$.active')),'true')".($status==='active'?"<>'false'":"='false'");
 if($category!==''){$where[]="JSON_UNQUOTE(JSON_EXTRACT(data,'$.category'))=?";$args[]=$category;}
 if($q!==''){$where[]="LOCATE(?,LOWER(JSON_UNQUOTE(JSON_EXTRACT(data,'$.name'))))>0";$args[]=mb_strtolower($q);}
 $filter=$where?' WHERE '.implode(' AND ',$where):'';
 if(($_GET['ids']??'')==='1')return ['ids'=>array_map(fn($r)=>(int)$r['id'],rows('SELECT id FROM ph_products'.$filter.' ORDER BY id',$args))];
 $limit=max(1,min(100,(int)($_GET['limit']??50)));$total=(int)one('SELECT COUNT(*) AS n FROM ph_products'.$filter,$args)['n'];$pages=max(1,(int)ceil($total/$limit));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*$limit;
 return ['items'=>array_map('catalog_product',rows('SELECT id,data FROM ph_products'.$filter.' ORDER BY id LIMIT '.$limit.' OFFSET '.$offset,$args)),'total'=>$total,'page'=>$page,'pages'=>$pages,'limit'=>$limit];
}
function products_route(string $route,string $method,array $b): void {global $user;
 if($route==='/admin/products/local-images'&&$method==='POST'){$paths=$b['paths']??null;if(!is_array($paths)||!count($paths)||count($paths)>100)fail('Bir seferde en fazla 100 görsel kontrol edilebilir.');$results=[];foreach($paths as $path){try{if(!is_string($path))fail('Görsel yolu geçersiz.');local_product_image($path);$results[]=['path'=>$path,'ok'=>true];}catch(ApiError $e){$results[]=['path'=>$path,'ok'=>false,'error'=>$e->getMessage()];}}out(['results'=>$results]);}

 if($route==='/admin/products/spreadsheet'&&$method==='POST'){
  $ps=$b['products']??null;if(!is_array($ps)||!count($ps)||count($ps)>10)fail('Aktarım grubu 1–10 ürün içermeli.');
  $count=atomic(function()use($ps){$seen=[];foreach($ps as $p){$identity=$p['importIdentity']??null;if(!valid_text($identity,1,2048)||isset($seen[$identity]))fail('Aktarım ürün kimliği geçersiz veya tekrarlı.');$seen[$identity]=true;if(isset($p['localImagePath'])){if(!is_string($p['localImagePath']))fail('Görsel yolu geçersiz.');$local=local_product_image($p['localImagePath']);$bytes=file_get_contents($local['path']);if($bytes===false)fail('Görsel okunamadı.');$id=substr(hash('sha256',$GLOBALS['user']['id'].':'.hash('sha256',$bytes)),0,40);sql('INSERT INTO ph_uploads(id,user_id,mime,data) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE id=id',[$id,$GLOBALS['user']['id'],$local['mime'],$bytes]);$p['images']=[$id];}validate_product($p);if(!count($p['images']))fail('Aktarılan ürün görseli eksik.');$key=hash('sha256','spreadsheet:'.$identity);$row=one('SELECT id,data FROM ph_products WHERE xml_key=? FOR UPDATE',[$key]);$old=$row?dec($row['data']):[];$next=array_replace($old,array_intersect_key($p,array_flip(['name','description','category','price','commissionPercent','requireText','requireImage','images','showOnHome'])));$next['active']=$old['active']??false;$next['showOnHome']=$p['showOnHome']??false;$next+=['kind'=>'name','color'=>'rose','tag'=>'Yeni'];if($row)$next['id']=(int)$row['id'];save_product($next,$key);}return count($ps);});out(['ok'=>true,'imported'=>$count]);
 }

 if($route==='/admin/categories'&&$method==='GET'&&($_GET['counts']??'')==='1'){$counts=rows("SELECT JSON_UNQUOTE(JSON_EXTRACT(data,'$.category')) AS name,COUNT(*) AS total FROM ph_products GROUP BY JSON_UNQUOTE(JSON_EXTRACT(data,'$.category'))");$names=dec(setting('categories','[]'));$map=[];foreach($counts as $r)$map[$r['name']]=(int)$r['total'];foreach($names as $name)$map[$name]??=0;ksort($map);out(array_map(fn($name)=>['name'=>$name,'total'=>$map[$name]],array_keys($map)));}
 if(($route==='/categories'||$route==='/admin/categories')&&$method==='GET')out(category_names($route==='/admin/categories'));
 if($route==='/admin/categories'&&in_array($method,['POST','DELETE'],true)){$name=trim(is_string($b['name']??null)?$b['name']:'');if(!valid_text($name,1,100)||in_array($name,['Tüm Ürünler','Favoriler'],true))fail('Geçerli bir kategori adı yazın.');atomic(function()use($name,$method){$names=dec(setting('categories','[]'));if($method==='POST'){if(in_array($name,category_names(true),true))fail('Bu kategori zaten var.',409);$names[]=$name;}else{if($name==='Genel')fail('Genel kategorisi silinemez.');foreach(rows('SELECT id,data FROM ph_products FOR UPDATE') as $row){$p=dec($row['data']);if($p['category']===$name){$p['category']='Genel';sql('UPDATE ph_products SET data=? WHERE id=?',[enc($p),$row['id']]);}}$names=array_values(array_filter($names,fn($n)=>$n!==$name));}set_setting('categories',enc($names));});out(['ok'=>true,'categories'=>category_names(true)]);}

 if($route==='/admin/products/bulk'&&$method==='DELETE')out(['deleted'=>delete_products($b['ids']??null)]);
 if(preg_match('~^/admin/products/(\d+)$~',$route,$m)&&$method==='DELETE')out(['deleted'=>delete_products([(int)$m[1]])]);
 if($route==='/products'&&$method==='GET'){$ps=array_values(array_filter(catalog(),fn($p)=>$p['active']??true));if(!is_dealer($user))foreach($ps as &$p){unset($p['dealerPrice'],$p['commissionPercent']);}out($ps);}
 if($route==='/admin/products'&&$method==='GET'&&($_GET['stats']??'')==='1')out(one("SELECT COUNT(*) AS total,COALESCE(SUM(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(data,'$.active')),'true')='false'),0) AS passive FROM ph_products"));
 if($route==='/admin/products'&&$method==='GET')out(isset($_GET['page'])||isset($_GET['ids'])?admin_product_page():catalog());
 if($route==='/admin/products'&&$method==='POST'){validate_product($b);$b['options']=product_options($b['options']??[]);$p=array_intersect_key($b,array_flip(['name','description','category','price','commissionPercent','requireText','requireImage','images','active','showOnHome','options']));$p+=['active'=>true,'kind'=>'name','color'=>'rose','tag'=>'Yeni'];out(save_product($p),201);}
 if($route==='/admin/products/bulk'&&$method==='PATCH'){if(!is_array($b['products']??null)||!count($b['products'])||count($b['products'])>1000)fail('Düzenlenecek ürünleri seçin.');$updates=$b['products'];$count=atomic(function()use($updates){$seen=[];foreach($updates as $patch){$id=$patch['id']??0;if(!is_int($id)||isset($seen[$id]))fail('Ürün seçimi geçersiz.');$seen[$id]=true;$row=one('SELECT id,data FROM ph_products WHERE id=? FOR UPDATE',[$id]);if(!$row)fail('Ürün bulunamadı.');$old=dec($row['data']);$old['id']=$id;$next=array_replace($old,array_intersect_key($patch,array_flip(['name','description','category','price','commissionPercent','requireText','requireImage','images','active','showOnHome','options'])));validate_product($next,$old);$next['options']=product_options($next['options']??[]);save_product($next);}return count($updates);});out(['updated'=>$count]);}
 if($route==='/uploads'&&$method==='POST'){$u=auth();$f=$_FILES['image']??null;if(!$f||is_array($f['name'])||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>5*1024*1024)fail('Tek bir JPG, PNG veya WebP görseli yükleyin (en fazla 5 MB).');$id=upload_save(file_get_contents($f['tmp_name']),(int)$u['id']);out(['id'=>$id,'url'=>($GLOBALS['config']['base_path']?:'').'/api.php?route=/uploads/'.$id],201);}
 if(preg_match('~^/uploads/([a-f0-9]{40})$~',$route,$m)&&$method==='GET')send_image($m[1]);
}
